package main
import (
	"database/sql"
	"log"
	_ "modernc.org/sqlite"
)
func InitDB(path string) (*sql.DB, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil { return nil, err }
	// Enable WAL mode for high performance
	if _, err := db.Exec("PRAGMA journal_mode=WAL;"); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

